// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        address sender = c.owner();
        vm.deal(sender, amount);
        Reverter reverter = new Reverter();
        bool ok = true;
        vm.prank(sender);
        try c.sendMoney(address(reverter), amount) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
